// ------------------------------------------------------------- Dynamic Routing Params
export function generateStaticParams() {
  return POSTS.map((p) => ({ slug: p.slug }));
}

// ------------------------------------------------------------- Dynamic SEO Metadata
export async function generateMetadata({
  params,
}: {
  params: Promise<{ slug: string }>;
}): Promise<Metadata> {
  const { slug } = await params;
  const post = POSTS.find((p) => p.slug === slug);
  if (!post) {
    return {};
  }
  return {
    title: post.seoTitle,
    description: post.seoDescription,
    openGraph: {
      title: post.seoTitle,
      description: post.seoDescription,
      type: "article",
    },
  };
}

// ------------------------------------------------------------- SVG Diagram Primitives
const SVGDefs = () => (
  <defs>
    <marker
      id="arrow"
      viewBox="0 0 10 10"
      refX={8}
      refY={5}
      markerWidth={5}
      markerHeight={5}
      orient="auto-start-reverse"
    >
      <path
        d="M 0 1 L 8 5 L 0 9"
        fill="none"
        stroke="rgba(255, 255, 255, 0.3)"
        strokeWidth={1.5}
        strokeLinecap="round"
        strokeLinejoin="round"
      />
    </marker>
  </defs>
);

function SVGBox({
  x,
  y,
  w,
  h = 36,
  text,
  accent = false,
}: {
  x: number;
  y: number;
  w: number;
  h?: number;
  text: string;
  accent?: boolean;
}) {
  return (
    <g>
      <rect
        x={x}
        y={y}
        width={w}
        height={h}
        rx={6}
        fill="var(--color-surface)"
        stroke={accent ? "var(--color-signal)" : "rgba(255, 255, 255, 0.16)"}
        strokeWidth={1}
        className={accent ? "stroke-signal" : "stroke-hairline-strong"}
      />
      <text
        x={x + w / 2}
        y={y + h / 2 + 4}
        textAnchor="middle"
        fontSize={11}
        className={accent ? "fill-signal font-mono font-medium" : "fill-paper font-mono"}
      >
        {text}
      </text>
    </g>
  );
}

// ------------------------------------------------------------- SVG Arrow Helper
function SVGArrow({
  x1,
  y1,
  x2,
  y2,
  label,
}: {
  x1: number;
  y1: number;
  x2: number;
  y2: number;
  label?: string;
}) {
  const midX = (x1 + x2) / 2;
  const midY = (y1 + y2) / 2;
  return (
    <g>
      <line
        x1={x1}
        y1={y1}
        x2={x2}
        y2={y2}
        stroke="rgba(255, 255, 255, 0.24)"
        strokeWidth={1}
        strokeDasharray={label ? "4 4" : undefined}
        markerEnd="url(#arrow)"
      />
      {label && (
        <text
          x={midX}
          y={midY - 4}
          textAnchor="middle"
          fontSize={8}
          className="fill-slate font-mono uppercase tracking-[0.1em]"
        >
          {label}
        </text>
      )}
    </g>
  );
}

